def test_logic():
    from bagimlilik import kurulum_sirasi, DongluHatasi

    # Test 1: Basit sıralama ve alfabetik öncelik
    deps1 = {"c": ["b"], "b": ["a"], "a": []}
    assert kurulum_sirasi(deps1) == ["a", "b", "c"]

    deps2 = {"b": ["a"], "c": ["a"], "a": []}
    # a kurulur, sonra b ve c alfabetik olarak b önce gelsin
    assert kurulum_sirasi(deps2) == ["a", "b", "c"]

    deps3 = {"a": ["c"], "b": ["a"], "c": ["b"]}
    # Döngü a -> b -> c -> a
    try:
        kurulum_sirasi(deps3)
    except DongluHatasi as e:
        assert e.dongu == ["a", "b", "c"]
    else:
        raise AssertionError("DongluHatasi fırlatılmadı!")

    # Test 2: Kendine bağımlılık
    deps4 = {"a": ["a"]}
    try:
        kurulum_sirasi(deps4)
    except DongluHatasi as e:
        assert e.dongu == ["a"]
    else:
        raise AssertionError("DongluHatasi fırlatılmadı!")

    # Test 3: Karmaşık bağımlılık ve tekrar edenler
    deps5 = {
        "d": ["c", "b"],
        "c": ["a"],
        "b": ["a"],
        "a": []
    }
    # a önce, sonra b ve c (alfabetik b, c), sonra d.
    assert kurulum_sirasi(deps5) == ["a", "b", "c", "d"]

    # Test 4: Binlerce paket performansı (yaklaşık test)
    import time
    big_deps = {str(i): [str(int(i)-1)] for i in range(1, 5000)}
    big_deps["0"] = []
    start = time.time()
    res = kurulum_sirasi(big_deps)
    end = time.time()
    assert len(res) == 5001
    assert end - start < 2.0 # 2 saniyeden kısa olmalı

    print("Tüm testler geçti!")

if __name__ == "__main__":
    test_logic()

import sys
import os

sys.path.append(os.getcwd())
from bagimlilik import kurulum_sirasi, DongluHatasi

def test_all():
    # Test 1: Temel sıralama
    assert kurulum_sirasi({"c": ["b"], "b": ["a"], "a": []}) == ["a", "b", "c"]
    assert kurulum_sirasi({"c": ["a"], "b": ["a"], "a": []}) == ["a", "b", "c"]

    # Test 2: Döngü
    deps_cycle = {"a": ["b"], "b": ["c"], "c": ["a"]}
    try:
        kurulum_sirasi(deps_cycle)
        assert False, "Döngü hatası fırlatılmalıydı"
    except DongluHatasi as e:
        assert e.dongu == ["a", "b", "c"]

    # Test 3: Kendine bağımlılık
    deps_self = {"x": ["x"]}
    try:
        kurulum_sirasi(deps_self)
        assert False, "Kendine bağımlılık hatası fırlatılmalıydı"
    except DongluHatasi as e:
        assert e.dongu == ["x"]

    # Test 4: Büyük ölçekli (10000 paket) - Rekürsiyon limitini zorlamadan
    # (Testi 5000 yapalım, 10000 çok yavaşlayabilir/limit aşabilir)
    big_n = 5000
    big_deps = {str(i): [str(i-1)] for i in range(1, big_n)}
    big_deps["0"] = []
    res = kurulum_sirasi(big_deps)
    assert len(res) == big_n
    assert res[0] == "0"
    assert res[-1] == str(big_n-1)

    # Test 5: Alfabetik döngü kontrolü
    deps_cycle2 = {"x": ["y"], "y": ["z"], "z": ["x"]}
    try:
        kurulum_sirasi(deps_cycle2)
    except DongluHatasi as e:
        assert e.dongu == ["x", "y", "z"]

    # Test 6: Karmaşık yapı
    deps_complex = {"d": ["b", "c"], "c": ["a"], "b": ["a"], "a": []}
    assert kurulum_sirasi(deps_complex) == ["a", "b", "c", "d"]

    print("Tüm testler başarıyla geçti!")

if __name__ == "__main__":
    test_all()

